  const cards=[['Логистика',rub(sum('logistics'))],['Хранение и приёмка',rub(sum('storage')+sum('acceptance'))],['Штрафы и удержания',rub(sum('penalties')+sum('deductions'))],['Эквайринг (уже в выплате)',rub(sum('acquiring'))]];
