const movementStyle=document.createElement('style');movementStyle.textContent='.movement-summary{display:grid;grid-template-columns:repeat(4,1fr);gap:8px;margin-bottom:14px}.movement-summary article,.supply-card{border:1px solid #e5eaf1;background:#f8fafc;border-radius:8px;padding:11px}.movement-summary small,.movement-summary b,.supply-card small,.supply-card b{display:block}.movement-summary small,.supply-card small{color:#718096;font-size:9px}.movement-summary b{font-size:16px;margin-top:4px}.supply-list{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin:12px 0}.supply-card b{font-size:11px}.supply-card small{margin-top:4px;line-height:1.45}.movement-note{border-left:3px solid #2563eb;background:#eff6ff;padding:10px 12px;margin:10px 0;color:#334155}.movement-note.warning{border-color:#d97706;background:#fffbeb}.stock-empty{padding:18px;border:1px dashed #cbd5e1;border-radius:8px;background:#f8fafc}.stock-empty b,.stock-empty span{display:block}.stock-empty span{margin-top:5px;color:#64748b}@media(max-width:800px){.movement-summary,.supply-list{grid-template-columns:1fr 1fr}}';document.head.append(movementStyle);

$('loadStocks').onclick=async()=>{if(!lastData){$('stockStatus').textContent='Сначала аудит';$('stockBody').innerHTML='<div class="stock-empty"><b>Нужен финансовый аудит</b><span>Он определит nmID товаров, по которым запрашивать остатки.</span></div>';return}const button=$('loadStocks');button.disabled=true;button.textContent='Загрузка…';try{const response=await fetch('/api/stocks',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({token:$('analyticsToken').value.trim(),nmIds:lastData.products.map(x=>x.nmId)})}),data=await response.json();if(!response.ok)throw new Error(data.error||'Ошибка загрузки остатков');loadedStocks=data.stocks;const enriched=await(await fetch('/api/inventory-analysis',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({stocks:loadedStocks,products:lastData.products,days:Math.max(1,Math.round((new Date($('dateTo').value)-new Date($('dateFrom').value))/86400000)+1)})})).json();$('stockStatus').textContent=`${data.rows} строк · ${new Date(data.generatedAt).toLocaleTimeString('ru-RU',{hour:'2-digit',minute:'2-digit'})}`;$('stockBody').innerHTML=enriched.inventory.length?`<div class="movement-note">Снимок сохранён в памяти и будет использован в сверке движения товара ниже.</div><div class="tablewrap"><table class="stock-table"><thead><tr><th>Товар / склад</th><th>Баркод</th><th>На складе</th><th>В пути</th><th>Продажи/день</th><th>Запас дней</th><th>Заказать</th><th>Статус</th></tr></thead><tbody>${enriched.inventory.map(x=>`<tr><td><b>nmID ${esc(x.nmId)}</b><small>${esc(x.warehouse||'Склад не указан')}</small></td><td>${esc(x.barcode||'—')}</td><td>${num(x.quantity)}</td><td>${num(Number(x.inWayToClient||0)+Number(x.inWayFromClient||0))}</td><td>${num(x.dailySales)}</td><td>${x.daysCover==null?'—':num(x.daysCover)}</td><td>${x.reorder==null?'—':num(x.reorder)}</td><td><span class="pill ${x.status==='critical'||x.status==='out'?'loss':x.status==='warning'?'warning':x.status==='healthy'?'healthy':'unknown'}">${x.status==='out'?'Нет остатка':x.status==='critical'?'До 7 дней':x.status==='warning'?'До 14 дней':x.status==='healthy'?'В норме':'Нет продаж'}</span></td></tr>`).join('')}</tbody></table></div>`:'<div class="stock-empty"><b>У выбранных товаров нет остатков на складах WB</b><span>Analytics-токен принят. WB вернул 204 No Content. Проверьте, что товары работают по FBW и фактически лежат на складах WB; остатки FBS здесь не отображаются.</span></div>'}catch(error){loadedStocks=[];$('stockStatus').textContent='Ошибка';$('stockBody').innerHTML=`<div class="stock-empty"><b>Не удалось загрузить остатки</b><span>${esc(error.message)}</span></div>`}finally{button.disabled=false;button.textContent='Загрузить остатки'}};

$('loadReconciliation').onclick=async()=>{if(!lastData){$('reconciliationStatus').textContent='Сначала аудит';$('reconciliationBody').textContent='Запустите финансовый аудит за нужный период.';return}const button=$('loadReconciliation');button.disabled=true;button.textContent='Сверяем…';$('reconciliationBody').textContent='Загружаем поставки и сопоставляем их с продажами и последним снимком остатков…';try{const response=await fetch('/api/reconciliation',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({token:$('suppliesToken').value.trim(),dateFrom:$('dateFrom').value,dateTo:$('dateTo').value,products:lastData.products,stocks:loadedStocks})}),data=await response.json();if(!response.ok)throw new Error(data.error||'Ошибка сверки');$('reconciliationStatus').textContent=`${data.summary.supplied} поставок · ${data.summary.total} товаров`;const cards=`<div class="movement-summary"><article><small>Поставки</small><b>${num(data.summary.supplied)}</b></article><article><small>Строк товаров</small><b>${num(data.summary.total)}</b></article><article><small>Полная сверка</small><b>нужен остаток на начало</b></article><article><small>Точно сверено</small><b>${num(data.summary.matched)}</b></article></div>`;const supplies=data.supplies?.length?`<h3>Какие поставки попали в расчёт</h3><div class="supply-list">${data.supplies.map(s=>`<article class="supply-card"><b>Поставка ${esc(s.id||'без ID')}</b><small>${esc(s.warehouseName||'Склад не указан')}</small><small>План: ${s.supplyDate?new Date(s.supplyDate).toLocaleDateString('ru-RU'):'—'} · факт: ${s.factDate?new Date(s.factDate).toLocaleDateString('ru-RU'):'—'}</small><small>Количество: ${num(s.quantity)} · принято: ${num(s.accepted)}</small></article>`).join('')}</div>`:'';const note=loadedStocks.length?'<div class="movement-note">Текущий остаток взят из Analytics. Для точной разницы также нужен остаток на начало выбранного периода; без него вывод о недостаче не строится.</div>':'<div class="movement-note warning">Остатки ещё не загружены. Сейчас можно проверить поставку, приёмку и продажи, но вывод о недостаче без фактического остатка предварительный.</div>';const table=data.rows.length?`<div class="tablewrap"><table class="stock-table"><thead><tr><th>Товар</th><th>Отгружено</th><th>Принято</th><th>Продано</th><th>Возвраты</th><th>Факт. остаток</th><th>Расчётный остаток</th><th>Разница</th><th>Что означает</th></tr></thead><tbody>${data.rows.map(x=>`<tr><td><b>nmID ${esc(x.nmId)}</b><small>${esc(x.barcode||'без баркода')}</small></td><td>${num(x.shipped)}</td><td>${num(x.accepted)}</td><td>${num(x.sold)}</td><td>${num(x.returned)}</td><td>${loadedStocks.length?num(x.stock):'не загружен'}</td><td>${x.expectedStock==null?'—':num(x.expectedStock)}</td><td>${x.gap==null?'—':num(x.gap)}</td><td><span class="pill ${x.status==='matched'?'healthy':x.status==='potential-loss'?'loss':'warning'}">${x.status==='insufficient'?'Недостаточно данных':x.status==='matched'?'Сходится':x.status==='potential-loss'?'Меньше ожидаемого':'Больше ожидаемого'}</span><small>${x.status==='insufficient'?'Нужен остаток на начало периода':x.status==='matched'?'Движение объяснено':x.status==='potential-loss'?`Не хватает ${num(Math.abs(x.gap))} шт.`:`Лишние или неучтённые ${num(Math.abs(x.gap))} шт.`}</small></td></tr>`).join('')}</tbody></table></div>`:'<div class="stock-empty"><b>За период нет движения</b><span>WB не вернул товарные строки по поставкам.</span></div>';$('reconciliationBody').innerHTML=cards+note+supplies+table}catch(error){$('reconciliationStatus').textContent='Ошибка';$('reconciliationBody').innerHTML=`<div class="stock-empty"><b>Сверка не выполнена</b><span>${esc(error.message)}</span></div>`}finally{button.disabled=false;button.textContent='Сверить движение'}};

// Repricer file import: turns CSV/XLSX rows into an explicit preview, never sends them automatically.
if($('priceFile'))$('priceFile').onchange=async e=>{
  const file=e.target.files[0]; if(!file)return;
  try{
    let rows=[];
    if(/\.xls[x]?$/i.test(file.name)){await xlsxReady;const book=XLSX.read(await file.arrayBuffer(),{type:'array',cellDates:false}),sheet=book.Sheets[book.SheetNames[0]],matrix=XLSX.utils.sheet_to_json(sheet,{header:1,defval:''}),header=(matrix[0]||[]).map(v=>String(v).trim().toLowerCase()),id=header.findIndex(v=>/nmid|nm_id|артикул/.test(v)),price=header.findIndex(v=>/цена|price/.test(v)),discount=header.findIndex(v=>/скид|discount/.test(v));if(id<0||price<0)throw new Error('В файле нужны колонки nmID и цена');rows=matrix.slice(1).map(r=>({nmId:String(r[id]).trim(),price:Number(String(r[price]).replace(',','.')),discount:discount>=0?Number(String(r[discount]).replace(',','.')):0}));}
    else{const lines=(await file.text()).replace(/^\uFEFF/,'').split(/\r?\n/).filter(Boolean),d=lines[0].includes(';')?';':',',header=csvLine(lines[0],d).map(v=>v.toLowerCase()),id=header.findIndex(v=>/nmid|nm_id|артикул/.test(v)),price=header.findIndex(v=>/цена|price/.test(v)),discount=header.findIndex(v=>/скид|discount/.test(v));if(id<0||price<0)throw new Error('В файле нужны колонки nmID и цена');rows=lines.slice(1).map(line=>{const r=csvLine(line,d);return{nmId:r[id]?.trim(),price:Number(String(r[price]).replace(',','.')),discount:discount>=0?Number(String(r[discount]).replace(',','.')):0}});}
    const valid=rows.filter(x=>/^\d+$/.test(x.nmId)&&Number.isFinite(x.price)&&x.price>0&&Number.isFinite(x.discount)&&x.discount>=0&&x.discount<=99);if(!valid.length)throw new Error('В файле нет корректных строк цены');const byId=new Map(repricerRows.map(x=>[x.nmId,x]));repricerRows=valid.map(x=>({...byId.get(x.nmId),...x,discountedPrice:Math.round(x.price*(1-x.discount/100)*100)/100}));renderPriceGrid();message('Файл загружен в предпросмотр. Изменения отправляются только из карточки товара.','success');
  }catch(error){message(error.message,'error')}finally{e.target.value=''}
};
// Identify every token's seller without exposing or storing the token.
const sellerIdentities=new Map();
function tokenAccountHint(token){try{const part=token.replace(/^Bearer\s+/i,'').split('.')[1];const value=JSON.parse(decodeURIComponent(escape(atob(part))));return String(value.uid??value.sid??value.oid??'')}catch{return ''}}
function attachSellerIdentity(inputId,caption){
  const input=$(inputId);if(!input)return;
  const wrap=input.closest('.stock-controls')||input.parentElement;
  const identity=document.createElement('small');identity.className='seller-identity';identity.textContent=caption+' · кабинет не определён';wrap.insertBefore(identity,input);
  identity.style.cssText='display:block;flex-basis:100%;order:-1;color:#64748b;font-size:10px;margin-bottom:-3px';
  input.addEventListener('blur',async()=>{
    const token=input.value.trim();if(token.length<20){identity.textContent=caption+' · вставьте токен для идентификации';return}
    const hint=tokenAccountHint(token);if(hint&&sellerIdentities.has(hint)){identity.textContent=caption+' · '+sellerIdentities.get(hint);return}
    identity.textContent=caption+' · определяем кабинет…';
    try{const r=await fetch('/api/seller-info',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({token})}),data=await r.json();if(!r.ok)throw new Error(data.error||'WB не подтвердил токен');const label=data.id?(data.name+' · ID '+data.id):data.name;sellerIdentities.set(hint||inputId,label);identity.textContent=caption+' · '+label;const distinct=new Set([...sellerIdentities.values()].map(x=>x.split(' · ID ')[1]||x));if(distinct.size>1)document.querySelectorAll('.seller-identity').forEach(x=>x.classList.add('mismatch'));}catch(error){identity.textContent=caption+' · '+error.message;identity.classList.add('error')}
  });
}
attachSellerIdentity('token','Финансы');
attachSellerIdentity('analyticsToken','Аналитика');
attachSellerIdentity('suppliesToken','Поставки');
attachSellerIdentity('repricerToken','Цены и скидки');
